/* Тесты по курсу «Экономика организаций (предприятий)», ДПО ВШЭ.
   Формат вопроса: [вопрос, [верный, дистрактор, дистрактор, дистрактор], пояснение, источник].
   Порядок вариантов перемешивается в приложении. */
window.TESTS = [];
function P(n, title, subtitle, qs) {
  window.TESTS.push({ id: 'p' + n, title: title, subtitle: subtitle,
    questions: qs.map(function (x) { return { t: x[0], o: x[1], a: 0, e: x[2], s: x[3] || '' }; }) });
}

